do(_Role, _Ext) ->
    case {whereis(lager_event), whereis(lager_event),
	  lager_config:get({lager_event, loglevel}, {0, []})}
	of
      {undefined, undefined, _} ->
	  fun () -> {error, lager_not_running} end();
      {undefined, _, _} ->
	  fun () -> {error, {sink_not_configured, lager_event}}
	  end();
      {__Pidrole_data_convert2465, _,
       {__Levelrole_data_convert2465,
	__Tracesrole_data_convert2465}}
	  when __Levelrole_data_convert2465 band 8 /= 0 orelse
		 __Tracesrole_data_convert2465 /= [] ->
	  lager:do_log(error,
		       [{module, role_data_convert}, {function, do},
			{line, 2465}, {pid, pid_to_list(self())}, {node, node()}
			| lager:md()],
		       io_lib:format("角色数据项不匹配, 转换失败:~w =/=~w ~w =/= ~w",
				     [element(2, _Role), 78, tuple_size(_Role),
				      tuple_size(#role{})]),
		       none, 4096, 8, __Levelrole_data_convert2465,
		       __Tracesrole_data_convert2465, lager_event,
		       __Pidrole_data_convert2465);
      _ -> ok
    end,
    {error, role_data_convert_failure}.

-spec parse_field([Type :: atom()], Data :: #role{},
		  list()) -> {ok, #role{}} |
			     {error, role_data_convert_failure}.

parse_field([], Role, _Ext) -> {ok, Role};
parse_field([Field | T],
	    Role = #role{id = Rid, name = Name}, Ext) ->
    case parse_field(Field, Role, Ext) of
      {ok, NewRole} -> parse_field(T, NewRole, Ext);
      {false, Reason} ->
	  case {whereis(lager_event), whereis(lager_event),
		lager_config:get({lager_event, loglevel}, {0, []})}
	      of
	    {undefined, undefined, _} ->
