parse_field(guild_bag, Role, Ext) ->
    NewGuildBag = case lists:keyfind(guild_bag, 1, Ext) of
		    {_, GuildBag} -> GuildBag;
		    _ -> Role#role.guild_bag
		  end,
    NewGuildBag2 = case guild_ver:do(NewGuildBag) of
		     {ok, NewGuildBag1}
			 when is_record(NewGuildBag1, guild_bag) ->
			 NewGuildBag1;
		     _Err ->
			 case {whereis(lager_event), whereis(lager_event),
			       lager_config:get({lager_event, loglevel},
						{0, []})}
			     of
			   {undefined, undefined, _} ->
			       fun () -> {error, lager_not_running} end();
			   {undefined, _, _} ->
			       fun () ->
				       {error,
					{sink_not_configured, lager_event}}
			       end();
			   {__Pidrole_data_convert2495, _,
			    {__Levelrole_data_convert2495,
			     __Tracesrole_data_convert2495}}
			       when __Levelrole_data_convert2495 band 8 /= 0
				      orelse
				      __Tracesrole_data_convert2495 /= [] ->
			       lager:do_log(error,
					    [{module, role_data_convert},
					     {function, parse_field},
					     {line, 2495},
					     {pid, pid_to_list(self())},
					     {node, node()}
					     | lager:md()],
					    io_lib:format("联盟背包版本转换失败", []),
					    none, 4096, 8,
					    __Levelrole_data_convert2495,
					    __Tracesrole_data_convert2495,
					    lager_event,
					    __Pidrole_data_convert2495);
			   _ -> ok
			 end,
			 NewGuildBag
		   end,
    {ok, Role#role{guild_bag = NewGuildBag2}};
