parse_field(exchange_item, Role, _Ext) ->
    case exchange_ver:do(Role) of
      {ok, NRole} -> {ok, NRole};
      _Err -> {false, lang:get(<<"商城物品转换版本失败"/utf8>>)}
    end;
parse_field(m_guild_dun,
	    Role = #role{m_guild_dun = MGuildDun}, _Ext) ->
    case guild_dun_ver:do(MGuildDun) of
      {ok, NewGuildDun} ->
	  {ok, Role#role{m_guild_dun = NewGuildDun}};
      _Err -> {false, lang:get(<<"公会副本转换版本失败"/utf8>>)}
    end;
